Đây là phương pháp hiện tại:

private async Task<IList<Item>> GetItemsAsync(string topItemId)
{
    var items = new List<Item>();
    var topItem = await GetItemAsync(topItemId);

    Stack<Item> stack = new Stack<Item>();
    stack.Push(topItem);

    while (stack.Count > 0)
    {
        var item = stack.Pop();
        items.Add(item);
        var subItems = await GetSubItemsAsync(item.SubId);

        foreach (var subItem in subItems)
        {
            stack.Push(subItem);
        }
    }

    return items;
}

Tôi đang nghĩ đến điều gì đó tương tự như sau, nhưng nó không hợp lại với nhau:

var tasks = stack.Select(async item =>
{
    items.Add(item);
    var subItems = await GetSubItemsAsync(item.SubId);

    foreach (var subItem in subItems)
    {
        stack.Push(subItem);
    }
}).ToList();

if (tasks.Any())
await Task.WhenAll(tasks);

