// trả về false nếu p (ID của nó) đã có sẵn
// nếu không thêm p vào danh sách và trả về true
công khai boolean tạo (Người p);

// trả về false nếu p (ID của nó) không được tìm thấy trong danh sách
// thay thế Người q có sẵn (q.ID == p.ID) với p và trả về true
công khai boolean cập nhật (Người p);

// trả về false nếu p (ID của nó) không được tìm thấy trong danh sách
// đánh dấu Người q có sẵn (q.ID == p.ID) là không hoạt động và trả về true
công khai boolean xóa (Người p);

}

