Đó là mẫu thiết kế JavaScript nào? Trong nơi làm việc của tôi, chúng tôi sử dụng thư viện ajax đơn giản để lấy dữ liệu trang và gửi các thay đổi lên máy chủ. Đôi khi chúng tôi cần thay đổi giá trị trường biểu mẫu. Tôi biết rằng các trường có thể là bất kỳ loại nào (hộp thả xuống, hộp văn bản, nút lựa chọn, v.v.) và một trong những nhiệm vụ khó chịu và nhàm chán nhất mà tôi thấy là ghi nhớ các trường ID để có thể thực hiện thao tác trên chúng (nhiệm vụ có thể kéo dài trong vài ngày, vì vậy tôi phải giữ các ID trong Notepad). Sau đó, tôi đã thiết kế một mẫu để dễ dàng làm việc với các trường.

function FormFieldsManager() {
    var FormMgr = {
        txtGradeName: function (txt) {
            if (txt) {
                $('#txtGradeName').val(txt);
            } else {
                return $('#txtGradeName').val();
            }
        },
        txtGradeDesc: function (txt) {
            if (txt) {
                $('#txtGradeDesc').text(txt);
            } else {
                return $('#txtGradeDesc').text();
            }
        },
        ddStatus: function (txt) {
            if (txt) {
                if (!isNaN(txt)) {
                    $("#ddStatus").val(txt);
                } else {
                    $("#ddStatus")[0].selectedIndex = txt;
                }
            } else {
                return $('#ddStatus :selected').val(); // giá trị được chọn: A
            }
        }
    };
    return FormMgr;
};

Để sử dụng hàm này, tôi chỉ cần gọi phương thức và tôi có thể điều hướng qua các trường biểu mẫu và nhận được JavaScript intellisense đầy đủ.

var form = FormFieldsManager();
form.txtGradeName('Software Developer'); // để đặt giá trị trường
form.txtGradeName(); // để lấy giá trị trường

