}

protected override void InitializeModules() {
Manager man= Container.Resolve<Manager>();
}

Câu hỏi là tôi có cần định nghĩa đối tượng quản lý của tôi như là tĩnh trong trường của nó để có thể truy cập trạng thái của nó hay không? Hoặc đây là mẫu chống lại hoặc xấu cho hiệu suất?

Cách đặt tên cho kẹp mà chỉ kẹp từ một bên? Clamp() là một hàm đảm bảo rằng biến được cung cấp nằm trong khoảng đã cho. Bạn có thể tìm thấy hàm như vậy trong .NET, trong Unity, và có lẽ ở bất cứ nơi nào. Trong khi nó hữu ích, tôi thường cần phải giới hạn giá trị của tôi từ một phía duy nhất. Ví dụ, để đảm bảo rằng float luôn dương hoặc luôn dương (như giá trị bán kính từ thanh kiểm tra). Tôi sử dụng tên ClampFromAbove() và ClampFromBelow(), nhưng tôi tự hỏi tên như vậy có tốt hay thậm chí hợp lệ ngữ pháp trong tiếng Anh lập trình không. Ngoài ra, nó có ý nghĩa để phân biệt trường hợp không âm. Bạn đặt tên cho hàm như thế nào? Cái gì đó như EnsureNonNegative()? Ý định của tôi là tạo cặp phương thức mở rộng và sử dụng chúng như sau:
var normalizedRadius = originalRadius.ClampFromBelow(0.0001);
var distance = someVector.Magnitude.ClampFromAbove(maxDistance);

So sánh hiệu năng của PHP và C# Tôi có một ứng dụng là một phần của ứng dụng console được viết bằng C# và một phần là ứng dụng web PHP. Ứng dụng console kết nối với nhiều thiết bị nối tiếp và đọc dữ liệu liên quan đến độ ẩm và nhiệt độ trong máy sấy ngũ cốc. Sau đó, ứng dụng lưu trữ thông tin vào cơ sở dữ liệu MySQL. Phần PHP đọc dữ liệu từ cơ sở dữ liệu MySQL và hiển thị thông tin cho người dùng (đơn giản). Tôi cũng đã viết một đoạn mã PHP để gửi email/tin nhắn SMS cho người dùng nếu một trong các mức nhiệt độ hoặc độ ẩm vượt quá mức cảnh báo (mức cảnh báo được đọc từ thiết bị và lưu trữ trong cơ sở dữ liệu MySQL). Hiện tại, tôi gửi dữ liệu đến trang PHP với mỗi "cập nhật" từ thiết bị (10 giây) và so sánh từng giá trị với giới hạn của nó. Nếu cần cảnh báo, tôi sẽ gửi cảnh báo và cập nhật cơ sở dữ liệu để chỉ ra rằng cảnh báo đã được gửi. Điều này trông giống như sau (ngôn ngữ giả):

IF độ ẩm > giới_hạn_cao_tối_cực THEN
  IF chưa_gửi_cảnh_báo_độ_ẩm_cao_tối_cực = FALSE THEN
    GỬI_CẢNH_BÁO();
    chưa_gửi_cảnh_báo_độ_ẩm_cao_tối_cực = TRUE;
  END IF;
END IF;
ELSE IF độ_ẩm > giới_hạn_cao_cảnh_báo THEN
  IF chưa_gửi_cảnh_báo_độ_ẩm_cao_cảnh_báo = FALSE THEN
    GỬI_CẢNH_BÁO();
    chưa_gửi_cảnh_báo_độ_ẩm_cao_cảnh_báo = TRUE;
  END IF;
END IF;
ELSE IF độ_ẩm < giới_hạn_thấp_tối_cực THEN
  IF chưa_gửi_cảnh_báo_độ_ẩm_thấp_tối_cực = FALSE THEN
    GỬI_CẢNH_BÁO();
    chưa_gửi_cảnh_báo_độ_ẩm_thấp_tối_cực = TRUE;
  END IF;
END IF;
ELSE IF độ_ẩm < giới_hạn_thấp_cảnh_báo THEN
  IF chưa_gửi_cảnh_báo_độ_ẩm_thấp_cảnh_báo = FALSE THEN
    GỬI_CẢNH_BÁO();
    chưa_gửi_cảnh_báo_độ_ẩm_thấp_cảnh_báo = TRUE;
  END IF;
END IF;

**Câu lệnh IF ở trên được lặp lại cho mỗi lần đọc nhiệt độ và độ ẩm từ thiết bị, số lượng có thể khá lớn.**

Liệu việc xử lý kiểu này có nên thực hiện trong ứng dụng Console của tôi? Sau đó, nếu cần cảnh báo, hãy đăng ký vào trang duy nhất để gửi email/tin nhắn SMS? Việc xử lý thông tin trong ứng dụng console sẽ giảm số lượng kết nối với cơ sở dữ liệu MySQL. Tuy nhiên, nếu cơ sở dữ liệu MySQL được lưu trữ cục bộ, liệu điều này có ảnh hưởng gì không? Tôi sẽ thực hiện đánh giá hiệu năng cho cả hai trường hợp (nếu thực sự xử lý trong ứng dụng console là cách tiếp cận đúng đắn), tuy nhiên còn rất nhiều mã cần phải chuyển đổi, vì vậy tôi nghĩ rằng tốt hơn là hỏi trước.

Ưu và nhược điểm của việc sử dụng Polling và Event trong JavaScript Tôi còn là người mới bắt đầu với JavaScript nên tôi đã tự hỏi về những mặt tích cực và tiêu cực của việc sử dụng thăm dò so với việc sử dụng các sự kiện trong JavaScript? Khi nào thì bạn nên sử dụng một cái hoặc cái khác? Bằng thăm dò, tôi xem xét bất kỳ hiệu ứng nào được kích hoạt trên một cái gì đó lặp đi lặp lại thường sử dụng setTimeout. Nhưng cũng ví dụ:

hàm render() {
Bloop.renderComponent(hộp, document.body);
requestAnimationFrame(render);
}

Cũng là thăm dò vì requestAnimationFrame(render) được gọi trước mỗi khung hình được gọi. Về cơ bản bất cứ điều gì phù hợp với định nghĩa này

Làm thế nào tôi có thể cải thiện thiết kế này để không cần quét động các lớp tại thời gian chạy? Tôi đang trong quá trình thiết kế lại một phần của dự án hiện tại liên quan đến quyền và ủy quyền của người dùng. Tôi có một giao diện được gọi là `IUserPermissions` bao gồm các thông tin này. Một phần của quyền của người dùng đó là **Vai trò** mà họ là thành viên của nó. Tôi đang cố gắng không vi phạm Nguyên tắc Mở/Đóng bằng cách thêm mọi vai trò có thể vào `IUserPermissions` như thuộc tính như sau:

```csharp
interface IUserPermissions
{
    bool IsAdmin { get; set; }
    bool IsDeveloper { get; set; }
    // Nhiều hơn nữa...
}
```

Tôi cảm thấy việc có một giao diện như sau sẽ phù hợp với OCP hơn:

```csharp
interface IUserPermissions
{
    ICollection<IRole> Roles { get; }
    bool IsInRole<T>() where T : IRole;  /* (Vì sự tiện lợi; Có lẽ sẽ được thực hiện như một phương thức mở rộng) */
}

interface IRole
{
    string Name { get; }
}

public class AdminRole : IRole
{
    public string Name { get { return "Admin"; } }
}
```

Vấn đề của tôi là làm thế nào để _thực hiện_ điều này. Tôi đang sử dụng API Vai trò ASP.NET làm kho lưu trữ, điều đó có nghĩa là tôi sẽ được cung cấp một mảng chuỗi các tên vai trò cho người dùng. Thực hiện của tôi đối với `IUserPermissions` sẽ phải bắt đầu với bộ sưu tập các chuỗi này và theo một cách nào đó hoạt động _lùi lại_, sau đó tạo ra một số `IRole` phù hợp để điền vào thuộc tính `Roles`. Điều này có thể được thực hiện bằng cách quét tập hợp để tìm `IRoles` với một hàm tạo tham số rỗng, tạo ra chúng, và đọc thuộc tính `Name` của chúng, nhưng... ôi trời ơi. Làm thế nào tôi có thể sửa thiết kế này để tôi không _phải_ làm điều đó?

Kiến trúc dựa trên mô-đun Đây có lẽ là một câu hỏi ngớ ngẩn, tôi xin lỗi nhưng tôi không thể tìm được cú pháp google để tìm câu trả lời. Hãy tưởng tượng một thuộc tính, như thế này:
     private int _type
     public int Type
     {
         get { return _type; }
         set
         {
             _type = value;
             //gây ra một sự kiện bằng ngôn ngữ hoặc công nghệ của bạn
             CallAFunction();
         }
     }
     Bây giờ, hãy tưởng tượng rằng CallAFunction làm một số tác vụ khá nghiêm trọng trong ứng dụng của bạn, tương tác với cơ sở dữ liệu thông qua một kho lưu trữ. Không phải là không hợp lý khi muốn có một bài kiểm tra đơn vị cho điều này, để chắc chắn rằng Loại được đặt thành bất cứ điều gì bạn đưa vào và kiểm tra rằng việc làm như vậy gây ra sự kiện mong đợi. Tuy nhiên, thiết lập thuộc tính với một bài kiểm tra sẽ gọi CallAFunction () có nghĩa là bạn không thực sự đang kiểm tra một "đơn vị" mã như vậy, và quan trọng hơn nữa là một bài kiểm tra đơn giản cho thuộc tính đơn giản này có thể yêu cầu chuẩn bị phức tạp hơn, bao gồm cả giả lập kho lưu trữ, điều này dường như là quá mức. Trong một số trường hợp bạn có thể chia những điều này bằng cách có CallAFunction được kích hoạt thông qua sự kiện. Nhưng đó không phải lúc nào cũng là trường hợp (tôi đang sử dụng WPF, và các sự kiện nổi lên đến XAML không thể kiểm tra). Cách tốt nhất để chia hai thứ này phụ thuộc lẫn nhau là gì?

Nhập các lớp cụ thể hay không Tôi có một giao diện TableSqlBuilder với phương thức getCreateTableSql. Giao diện này được sử dụng trong một số lớp khác như sau:

function createTable( $tableDefinition ) {
    $sql = $this->tableSqlBuilder->getCreateTableSql( $tableDefinition );
    $this->db->execute( $sql );
}

Giao diện TableSqlBuilder có nhiều thực hiện, chẳng hạn như SQLiteTableSqlBuilder và MySQLTableSqlBuilder. SQLiteTableSqlBuilder ban đầu tạo tất cả các câu lệnh SQL của riêng nó và có các phương thức để tạo câu lệnh SQL cho một chỉ mục hoặc cho một trường. Hóa ra là chức năng của các phương thức này được cần thiết ở những nơi khác, vì vậy nó đã được tách ra thành một SQLiteFieldSqlBuilder và một SQLiteIndexSqlBuilder. Những lớp này được khởi tạo bởi SQLiteTableSqlBuilder - do đó chúng không được tiêm, và SQLiteTableSqlBuilder phụ thuộc vào những lớp cụ thể này. Tôi không chắc liệu điều này có nên thay đổi để có các trình tạo câu lệnh SQL trường và chỉ mục được tiêm hay không.

Mặt khác, việc này mang lại sự linh hoạt hơn. Nó cũng cho phép giả lập hành vi này trong các bài kiểm tra. Mặt khác, sự ràng buộc và tính linh hoạt hiện tại giống như trước khi mã được chia thành các lớp mới. Khi sử dụng cách tiếp cận tiêm, các kiểu được chấp nhận có thể là FieldSqlBuilder và IndexSqlBuilder, cả hai đều là các giao diện được thực hiện bởi các lớp cụ thể hiện tại. Tuy nhiên, điều này có nghĩa là bạn có thể kết thúc với một MySqlIndexBuilder trong một SQLiteTableBuilder, điều này rõ ràng là cần tránh. Tôi cũng có thể chỉ định kiểu cho lớp cụ thể, giả vờ rằng nó là một giao diện, loại bỏ sự phụ thuộc miễn là việc xây dựng xảy ra bên ngoài trình tạo câu lệnh SQL bảng. Bạn nghĩ rằng các đối tác này có nên được tiêm hay đây là một ngoại lệ hợp lệ khi tốt nhất không nên đi theo con đường này?

Cấu hình Jenkins và Tomcat sử dụng Puppet trên Vagrant Tôi đang thiết lập môi trường phát triển CI đầu tiên với `Spring` + `jenkins` + `Tomcat`. Hiện tại chỉ là giai đoạn thử nghiệm/học tập, nhưng trong tương lai gần tôi sẽ bắt đầu một dự án mới với các đồng nghiệp. Vì vậy tôi muốn thiết lập môi trường phát triển ảo hóa và y hệt nhau trên tất cả máy phát triển cũng như trên máy chủ sản xuất. Tôi chọn sử dụng `Vagrant` và cố gắng viết các kịch bản `puppet` không chỉ cài đặt mà còn cấu hình mọi thứ để mỗi người chúng tôi đều có cùng các plugin `jenkins`, cùng tên đăng nhập và mật khẩu cho `jenkins` và `tomcat`, và sau khi gọi `vagrant up` chúng tôi đã sẵn sàng làm việc. Cho đến nay tôi đã thực hiện được việc cài đặt các thành phần cần thiết và chuyển tiếp cổng. File `Vagrantfile` của tôi trông như thế này (không có chú thích):

VAGRANTFILE_API_VERSION = "2"
Vagrant.configure(VAGRANTFILE_API_VERSION) do |config|
  config.vm.box = "precise32"
  config.vm.box_url = "http://files.vagrantup.com/precise32.box"
  config.vm.network :forwarded_port, guest: 80, host: 8090
  config.vm.network :forwarded_port, guest: 8080, host: 8091
  config.vm.network :private_network, ip: "192.168.33.10"
  config.vm.provision :puppet do |puppet|
    puppet.manifests_path = "puppet/"
    puppet.manifest_file  = "default.pp"
    puppet.options = ['--verbose']
  end
end

Đây là file `puppet` của tôi:

Exec { path => [ "/bin/", "/sbin/" , "/usr/bin/", "/usr/sbin/" ] }
class system-update {
  exec { 'apt-get update':
    command => 'apt-get update',
  }
  $sysPackages = [ "build-essential" ]
  package { $sysPackages:
    ensure => "installed",
    require => Exec['apt-get update'],
  }
}
class tomcat {
  package { "tomcat":
    ensure  => present,
    require => Class["system-update"],
  }
  service { "tomcat":
    ensure  => "running",
    require => Package["tomcat"],
  }
}
class jenkins {
  package { "jenkins":
    ensure => present,
    require => Class["system-update"],
  }
  service { "jenkins":
    ensure => "running",
    require => Package["jenkins"],
  }
}
include system-update
include tomcat
include jenkins

Bây giờ, khi tôi chạy `vagrant provision` và truy cập `http://localhost:8091/` tôi thấy `jenkins` đang chạy, vì vậy kịch bản trên hoạt động tốt. Bước tiếp theo là cấu hình `jenkins` và `tomcat` bằng cách mở rộng các kịch bản `puppet` trên. Tôi chưa có nhiều kinh nghiệm về CI. Sau khi tìm kiếm trên mạng tôi đã tìm thấy một vài hướng dẫn về việc cấu hình `jenkins` (đây là một trong số đó). Tôi rất muốn chuyển cấu hình được trình bày trong hướng dẫn này sang file `puppet` để khi tôi chia sẻ file `Vagrantfile` và `puppet` với các đồng nghiệp, tôi có thể đảm bảo rằng mọi người đều có cùng một thiết lập. Tuy nhiên tôi cũng chưa quen thuộc với việc sử dụng `puppet`, tôi không biết phải làm thế nào để thực hiện điều này. Mọi sự giúp đỡ sẽ được đánh giá cao.

Cách thay đổi chữ ký phương thức cho việc thực hiện các lớp trong PHP Có cách nào để khắc phục sự thiếu sót của PHP trong việc không hỗ trợ Generic mà cho phép kiểm tra mã tĩnh để phát hiện sự nhất quán về kiểu dữ liệu không? Tôi có một lớp trừu tượng mà tôi muốn kế thừa và cũng thực thi rằng một trong các phương thức thay đổi từ việc nhận một tham số của một kiểu dữ liệu thành một tham số là lớp con của tham số đó.

Ví dụ:

abstract class AbstractProcessor {
    abstract function processItem(Item $item);
}

class WoodProcessor extends AbstractProcessor {
    function processItem(WoodItem $item) {}
}

Điều này không được phép trong PHP vì nó thay đổi chữ ký phương thức, điều này không được phép. Với phong cách Java của Generic, bạn có thể làm điều gì đó như sau:

abstract class AbstractProcessor<T> {
    abstract function processItem(T $item);
}

class WoodProcessor extends AbstractProcessor<WoodItem> {
    function processItem(WoodItem $item) {}
}

Nhưng rõ ràng PHP không hỗ trợ những thứ như vậy. Khi tìm kiếm trên Google về vấn đề này, mọi người đề xuất sử dụng instanceof để kiểm tra lỗi trong thời gian chạy, ví dụ:

class WoodProcessor extends AbstractProcessor {
    function processItem(Item $item) {
        if (!($item instanceof WoodItem)) {
            throw new \InvalidArgumentException("item of class ".get_class($item)." is not a WoodItem");
        }
    }
}

Tuy nhiên, cách này chỉ hoạt động trong thời gian chạy, nó không cho phép bạn kiểm tra mã của mình để tìm lỗi bằng phân tích tĩnh - vậy có cách nào hợp lý để xử lý điều này trong PHP không? Một ví dụ hoàn chỉnh hơn về vấn đề này là:

class StoneItem extends Item {}
class WoodItem extends Item {}

class WoodProcessedItem extends ProcessedItem {
    function __construct(WoodItem $woodItem) {}
}

class StoneProcessedItem extends ProcessedItem {
    function __construct(StoneItem $stoneItem) {}
}

abstract class AbstractProcessor {
    /**
     * @return ProcessedItem
     */
    abstract function processItem(Item $item);

    function processAndBoxItem(Box $box, Item $item) {
        $processedItem = $this->processItem($item);
        $box->insertItem($item);
    }

    // Nhiều hàm khác có thể gọi processItem
}

class WoodProcessor extends AbstractProcessor {
    function processItem(Item $item) {
        return new ProcessedWoodItem($item); // Có lỗi trong kiểm tra mã
    }
}

class StoneProcessor extends AbstractProcessor {
    function processItem(Item $item) {
        return new ProcessedStoneItem($item); // Có lỗi trong kiểm tra mã
    }
}

Vì tôi truyền vào chỉ một đối tượng 'Item' cho 'new ProcessedWoodItem($item)' và nó mong đợi một đối tượng WoodItem làm tham số, nên kiểm tra mã cho thấy có lỗi.

Đây có phải là cách sử dụng đúng mẫu Repository trong ứng dụng ASP .NET MVC thực hiện Entity Framework? Ứng dụng ASP .NET MVC này thực hiện Entity Framework. Tôi đã khai báo các kho lưu trữ trong DbContext như sau:

public class CompanyDbContext : DbContext
{
