    public DbSet<Customer> Customers { get; set; }

    public DbSet<Order> Orders { get; set; }

    public DbSet<CustomerOrder> CustomerOrders { get; set; }

    private IGeneralEntityRepository<Customer> customersRepository;

    private IGeneralEntityRepository<Order> ordersRepository;

    // ...................
}

Như vậy, chúng ta có thể khai báo và khởi tạo CompanyDbContext trong một bộ điều khiển và sau đó truy cập vào các kho lưu trữ bằng cách sử dụng instance của CompanyDbContext. Điều này có đúng không? Hoặc tôi nên tạo một lớp "Unit Of Work" riêng để truy cập vào các kho lưu trữ?

Kéo dài lớp học hay tạo một ví dụ? Tôi đang đọc cuốn sách Pro PHP và jQuery và muốn xây dựng lại ví dụ trong đó. Tác giả đã tạo một lớp kết nối cơ sở dữ liệu như sau:

class DB_Connect {
    protected $db;

    protected function __construct($dbo = NULL) {
        if (is_object($db)) {
            $this->db = $db;
        } else {
            // Các hằng được định nghĩa trong /sys/config/db-cred.inc.php
            $dsn = "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME;

            try {
                $this->db = new PDO($dsn, DB_USER, DB_PASS);
            } catch (Exception $e) {
                die ($e->getMessage());
            }
        }
    }
}

Sau đó, lớp này được mở rộng bởi lớp chính của ứng dụng để truy cập vào đối tượng cơ sở dữ liệu. Tại sao lại thực hiện theo cách này? Chúng ta có thể tạo một instance của `DB_Connect` trong lớp chính không? Cách tiếp cận này có những lợi ích gì?

Hợp thành so với thừa kế Đây là những gì được cung cấp:

