Ngoại lệ so với mã lỗi khi làm việc với thiết bị Đội của tôi đang bắt đầu một dự án mới. Một trong những thành phần ở ranh giới của hệ thống là thành phần tương tác với máy in thông qua thành phần COM bên ngoài (được tham chiếu như là thư viện DLL thông thường). Thành phần COM trả về mã số nguyên nếu có lỗi xảy ra trong khi thực thi lệnh. Hãy xem xét một đoạn mã cụ thể:

public class OperationException : Exception
{
    public int ErrorCode { get; private set; }
    public string ErrorDescription { get; private set; }

    public OperationException(int errorCode, string errorDescription)
    {
        ErrorCode = errorCode;
        ErrorDescription = errorDescription;
    }
}

//Cách ném ngoại lệ
public class Provider1 : IFrProvider
{
    private readonly IDrvFR48 driver;

    public string GetSerialNumber()
    {
        //Phải đọc trạng thái trước khi lấy SerialNumber
        int resultCode = driver.ReadEcrStatus();

        if (resultCode != 0)
        {
            throw new OperationException(resultCode, driver.ErrorDescription);
        }

        return driver.SerialNumber;
    }
}

//Cách trả về tham số ra
public class Provider2 : IFrProvider
{
    private readonly IDrvFR48 driver;

    public string GetSerialNumber(out Result result)
    {
        //Phải đọc trạng thái trước khi lấy SerialNumber
        int resultCode = driver.ReadEcrStatus();

        if (resultCode != 0)
        {
            result = new Result(resultCode, driver.ErrorDescription);
            return null;
        }

        result = new Result(0, null);
        return driver.SerialNumber;
    }
}

//Cách đặt thuộc tính LastResult
public class Provider3 : IFrProvider
{
    private readonly IDrvFR48 driver;

    public Result LastResult
    {
        get
        {
            return new Result(driver.ErrorCode, driver.ErrorDescription);
        }
    }

    public string GetSerialNumber()
    {
        //Phải đọc trạng thái trước khi lấy SerialNumber
        if (driver.GetECRStatus() == 0)
            return driver.SerialNumber;

        return null;
    }
}

