Đóng góp vào hệ thống lưu trữ cho một trò chơi Tôi đang làm việc trên một trò chơi nhiều người chơi, trong đó mỗi người chơi có nhiều kho để lưu trữ vật phẩm. Kho là hệ thống cho phép người dùng gửi tiền và lấy lại. Ví dụ về các loại kho:

 * **Hàng tồn kho**: Giống như hàng tồn kho của WoW, bạn có thể thêm vật phẩm, rơi vật phẩm, di chuyển vật phẩm từ khe cắm này sang khe cắm khác.

 * **Ngân hàng**: Ngân hàng là những gì bạn có thể gọi là siêu hàng tồn kho, có giới hạn khoảng 300 vật phẩm **cho mỗi tab** Ngân hàng có thể có tối đa 10 tab sẽ lưu trữ vật phẩm. Tổng số vật phẩm được phép trong ngân hàng là 3000 (10 tab nhân với 300 vật phẩm mỗi tab). Tuy nhiên, trong ngân hàng, tất cả các vật phẩm đều có thể chồng lên nhau.

 * **Thiết bị**: Thiết bị giống như Hàng tồn kho, chỉ có các khe cắm sắp xếp, ví dụ: Helm, Thân và tổng cộng có 8 khe cắm.

 * **Hộp và các loại khác**: Giống như Ngân hàng chỉ không có tab.

**Một vật phẩm trong trò chơi** Mỗi vật phẩm có ID của riêng nó. Chỉ **nhất định** các vật phẩm có thể chồng lên nhau, trừ khi loại kho là Ngân hàng hoặc Hộp. Tôi đã tạo ra một hệ thống sẽ giúp tôi dễ dàng quản lý các kho và có lớp trừu tượng mà mỗi lớp loại kho sẽ mở rộng nó:

   public abstract class PlayerItemStorage {
     private int size;
     /**
       * Các vật phẩm
       */
     private PlayerItem[] items;
     /**
       * Đôi khi, theo mặc định, các mục trong kho có ID + 1, do
       * giao diện của khách hàng. Không có giải thích chính xác về nó, nhưng tính năng duy nhất
       * không làm điều đó là thiết bị và có thể BoB
       */
     private boolean increasedItem = true;
     public PlayerItemStorage(int storageSize) {
       this.items = new PlayerItem[storageSize];
       this.size = storageSize;
     }
     public PlayerItemStorage(PlayerItem[] items) {
       this.items = items;
       this.size = items.length;
     }
     /**
       * Đặt lại kho
       */
     public void resetStorage() {
       this.items = new PlayerItem[this.size];
     }
     /**
       * Lấy danh sách vật phẩm
       * @return Danh sách PlayerItem
       */
     public PlayerItem[] getItems() {
       return this.items;
     }
     /**
       * Đếm có bao nhiêu vật phẩm có cùng ID.
       * @param id ID vật phẩm
       * @return số lượng
       */
     public int count(int id) {
       int count = 0;
       for (PlayerItem item : this.items) {
         if (this.getId(item) == id) {
           count++;
         }
       }
       return count;
     }
     /**
       * Đếm có bao nhiêu vật phẩm trong hàng tồn kho
       * không bao gồm số lượng, chỉ là các đối tượng vật phẩm.
       * @return số lượng
       */
     public int countItems() {
       int count = 0;
       for (PlayerItem item : this.items) {
         if (this.getId(item) > 0 && item.getAmount() > 0) {
           count++;
         }
       }
       return count;
     }
     /**
       * Lấy chiều dài của kho
       * @return
       */
     public int getLength() {
       return this.items.length;
     }
     /**
       * Kiểm tra kho còn bao nhiêu khe cắm trống
       * @return
       */
     public int freeSlots() {
       int slots = 0;
       for (PlayerItem item : this.items) {
         if (this.getId(item) <= 0) {
           slots++;
         }
       }
       return slots;
     }
     /**
       * Tìm ID vật phẩm trong khe cắm sớm nhất.
       * @param id ID vật phẩm
       * @return ID khe cắm
       */
     public int find(int id) {
       for (int i = 0; i < this.items.length; i++) {
         PlayerItem item = this.items[i];
         if (this.getId(item) == id && item.getAmount() > 0) {
           return i;
         }
       }
       return -1;
     }
     /**
       * Lấy khe cắm trống sớm nhất
       * @return ID khe cắm
       */
     public int getFreeSlot() {
       for (int i = 0; i < this.items.length; i++) {
         if (this.getId(i) <= 0) {
           return i;
         }
       }
       return -1;
     }
     /**
       * Kiểm tra xem vật phẩm có tồn tại trong khe cắm được cho trước, với số lượng và
       * ID vật phẩm.
       * @param id ID vật phẩm
       * @param amount Số lượng vật phẩm
       * @param slot ID khe cắm
       * @return boolean
       */
     public boolean containsInSlot(int id, int amount, int slot) {
       int found = 0;
       if (this.items[slot].getAlpha() == id) {
         for (int i = 0; i < this.items.length; i++) {
           PlayerItem item = this.items[i];
           if (this.getId(item) == id) {
             if (item.getAmount() >= amount) {
               return true;
             } else {
               found++;
             }
           }
         }
         if (found >= amount) {
           return true;
         }
         return false;
       }
       return false;
     }
     /**
       * Kiểm tra xem vật phẩm có tồn tại trong kho
       */
     public boolean contains(int id) {
       for (PlayerItem item : this.items) {
         if (this.getId(item) == id) {
           return true;
         }
       }
       return false;
     }
     /**
       * {@link #increasedItem}
       * @param i Chỉ số
       * @return ID vật phẩm thực
       */
     private int getId(int i) {
       if (this.increasedItem) {
         return this.items[i].getAlpha();
       }
       return this.items[i].getId();
     }
     /**
       * {@link #increasedItem}
       * @param item Đối tượng PlayerItem
       * @return ID vật phẩm thực
       */
     private int getId(PlayerItem item) {
       if (this.increasedItem) {
         return item.getAlpha();
       }
       return item.getId();
     }
     public abstract boolean add(int id, int amount);
     public abstract boolean remove(int id, int amount, int fromSlot);
   }

