Cấu trúc có nên được tái cấu trúc thành các cấu trúc nhỏ hơn không? Trong một trong các dự án (viết bằng C), tôi có đoạn mã trông giống như thế này (tên các biến được viết sai để không tiết lộ chi tiết của dự án):

typedef struct Module_s {
    /* Các trường này được phân tích bởi hàm f1() */
    S1 *s11;
    S2 *s12;
    size_t n11;
    size_t n12;
    int i11;
    /* Các trường này được phân tích bởi hàm f2() */
    S2 *s21;
    S3 *s22;
    S4 *s23;
    char *c24;
    /* Các trường này được thiết lập bởi hàm f3() và sau đó */
    void *v31;
    bool b32;
    S5 s33[N];
    bool b34;
} Module_t;

{
    /* Đọc chỉ header của file và
     * phân tích 5 trường đầu tiên để xác định cách tải phần còn lại. */
    Module_t *module = f1(input_file);
    /* Đọc phần còn lại của file sử dụng thông tin được thiết lập bởi f1()
     * và xác định cách f3() nên xử lý trước nó. */
    f2(input_file, module);
    /* Xử lý trước file sử dụng thông tin được cung cấp bởi f1() và f2(). */
    f3(module);
    /* Xử lý file sử dụng thông tin được cung cấp bởi f2() và f3(). */
    f4(module);
}

Vậy câu hỏi là, việc chia tách cấu trúc 'Module_t' thành 3 phần nhỏ hơn, mỗi phần chứa các trường tương ứng, được thiết lập bởi mỗi hàm là một ý tưởng hay không? Mỗi hàm sẽ chỉ chấp nhận và trả về một phần nhỏ hơn của 'Module_t', điều này có thể tốt nhưng cũng có thể làm cho việc phát triển sau này phức tạp hơn khi các liên kết giữa các phần trở nên phức tạp hơn - và giữ tất cả các trường phụ thuộc ở một vị trí duy nhất thì có vẻ đơn giản hơn. Điều tôi đang nghĩ đến là:

typedef struct SS1_s {
    /* Các trường này được phân tích bởi hàm f1() */
    S1 *s11;
    S2 *s12;
    size_t n11;
    size_t n12;
    int i11;
} SS1_t;

typedef struct SS2_s {
    /* Các trường này được phân tích bởi hàm f2() */
    S2 *s21;
    S3 *s22;
    S4 *s23;
    char *c24;
} SS2_t;

typedef struct SS3_s {
    /* Các trường này được thiết lập bởi hàm f3() và sau đó */
    void *v31;
    bool b32;
    S5 s33[N];
    bool b34;
} SS3_t;

typedef struct Module_s {
    SS1_t ss1;
    SS2_t ss2;
    SS3_t ss3;
} Module_t;

{
    /* Đọc chỉ header của file và
     * phân tích 5 trường đầu tiên để xác định cách tải phần còn lại. */
    SS1_t *ss1 = f1(input_file);
    /* Đọc phần còn lại của file sử dụng thông tin được thiết lập bởi f1()
     * và xác định cách f3() nên xử lý trước nó. */
    SS2_t *ss2 = f2(input_file, ss1);
    /* Xử lý trước file sử dụng thông tin được cung cấp bởi f1() và f2(). */
    SS3_t *ss3 = f3(ss1, ss2);
    /* Kết hợp module và
