Cách tốt nhất để tạo ra một AI bán thông minh cho trò chơi tic tac toe là gì? Tôi đang cố gắng tạo ra một trò chơi Tic-Tac-Toe hiệu quả và nhỏ gọn bằng C. Tôi đã thực hiện mọi thứ ngoại trừ AI cho máy tính. Các ô của tôi cơ bản là các struct trong một mảng với giá trị được gán dựa trên từng ô. Ví dụ s[1].value = 1; do đó đó là _x_ và sau đó giá trị 3 sẽ là _o_. Câu hỏi của tôi là cách tốt nhất để tạo ra một AI chơi game khá tốt cho trò chơi Tic-Tac-Toe là gì? Tôi không muốn sử dụng minimax vì nó không phù hợp với nhu cầu của tôi. Vậy làm thế nào để tránh nhiều câu lệnh _if_ và làm cho nó hiệu quả hơn? Đây là phần còn lại của mã:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct state{ // định nghĩa
int state; // 0 là hòa, 1 là người dùng thua, 2 là người dùng thắng, 3 là trò chơi đang diễn ra
int moves;
};

struct square{ // một ô trên bàn cờ
int value; // 1 là x, 3 là o
char sign; // không có dấu cách
};

struct square s[9]; // thiết lập cấu trúc
struct state gamestate = {0,0}; //không có gì

void setUpGame(){ // thiết lập trò chơi
int i = 0;
for(i = 0; i < 9; i++){
s[i].value = 0;
s[i].sign = ' ';
}
gamestate.moves=0;
printf("\nChào bạn! Bạn là \"x\"! Tôi là \"o\"! Chúc may mắn :)\n");
}

void displayBoard(){// hiển thị bàn cờ
printf("\n %c | %c | %c\n", s[6].sign, s[7].sign, s[8].sign);
printf("-----------\n");
printf(" %c | %c | %c\n", s[3].sign, s[4].sign, s[5].sign);
printf("-----------\n");
printf(" %c | %c | %c\n\n", s[0].sign, s[1].sign, s[2].sign);
}

void getHumanMove(){ // nhận lượt đi của người dùng
int i;
while(1){
printf(">>:");
char line[255]; // nhập lượt đi để chơi
fgets(line, sizeof(line), stdin);
while(sscanf(line, "%d", &i) != 1) { //1 khớp với ký tự định nghĩa trong dòng đầu vào
printf("Xin lỗi, đó không phải là lượt đi hợp lệ!\n");
fgets(line, sizeof(line), stdin);
}
if(s[i-1].value != 0){printf("Xin lỗi, lượt đi đó đã được sử dụng rồi!\n\n");continue;}
break;
}
s[i-1].value = 1;
s[i-1].sign = 'x';
gamestate.moves++;
}

int sum(int x, int y, int z){return(x*y*z);}

void getCompMove(){ // nhận lượt đi của máy tính
// ...
}

void checkWinner(){ // kiểm tra người thắng cuộc
int i;
for(i = 6; i < 9; i++){ // kiểm tra cột
if((sum(s[i].value,s[i-3].value,s[i-6].value)) == 8){printf("Người thắng cuộc là o!\n");gamestate.state=1;}
if((sum(s[i].value,s[i-3].value,s[i-6].value)) == 1){printf("Người thắng cuộc là x!\n");gamestate.state=2;}
}
for(i = 0; i < 7; i+=3){ // kiểm tra hàng
if((sum(s[i].value,s[i+1].value,s[i+2].value)) == 8){printf("Người thắng cuộc là o!\n");gamestate.state=1;}
if((sum(s[i].value,s[i+1].value,s[i+2].value)) == 1){printf("Người thắng cuộc là x!\n");gamestate.state=2;}
}
if((sum(s[0].value,s[4].value,s[8].value)) == 8){printf("Người thắng cuộc là o!\n");gamestate.state=1;}
if((sum(s[0].value,s[4].value,s[8].value)) == 1){printf("Người thắng cuộc là x!\n");gamestate.state=2;}
if((sum(s[2].value,s[4].value,s[6].value)) == 8){printf("Người thắng cuộc là o!\n");gamestate.state=1;}
if((sum(s[2].value,s[4].value,s[6].value)) == 1){printf("Người thắng cuộc là x!\n");gamestate.state=2;}
}

void playGame(){ // bắt đầu chơi trò chơi
gamestate.state = 3; // thiết lập trạng thái trò chơi
srand(time(NULL));
int temp = (rand()%2) + 1;
if(temp == 2){ // nếu máy tính đi trước
temp = (rand()%2) + 1;
if(temp == 2){
s[4].value = 2; s[4].sign = 'o';
gamestate.moves++;
}else{
s[2].value = 2; s[2].sign = 'o';
gamestate.moves++;
}
}

displayBoard();
while(gamestate.state == 3){
if(gamestate.moves<10);
getHumanMove();
if(gamestate.moves<10);
getCompMove();
checkWinner();
if(gamestate.state == 3 && gamestate.moves==9){
printf("Trò chơi kết thúc hòa :p\n");
break;
}
displayBoard();
}
}

int main(int argc, const char *argv[]){
printf("Chào mừng đến với Tic Tac Toe\nby The Elite Noob\nNhập 1-9 để đi nước đi, phím số chuẩn\n1 là dưới bên trái, 9 là trên bên phải\n");
