CalculateResult2.cpp:

#include "stdafx.h"
#include <iostream>
#include <string>
using namespace std;
int CalculateResult2(int nX, char chOperation, int nY, char chOperation2, int nZ)
{
if (chOperation == '+' && chOperation2 == '+')
return nX + nY + nZ;
if (chOperation == '+' && chOperation2 == '-')
return nX + nY - nZ;
if (chOperation == '+' && chOperation2 == '*')
return nX + nY * nZ;
if (chOperation == '+' && chOperation2 == '/')
return nX + nY / nZ;
if (chOperation == '-' && chOperation2 == '+')
return nX - nY + nZ;
if (chOperation == '-' && chOperation2 == '-')
return nX - nY - nZ;
if (chOperation == '-' && chOperation2 == '*')
return nX - nY * nZ;
if (chOperation == '-' && chOperation2 == '/')
return nX - nY / nZ;
if (chOperation == '*' && chOperation2 == '+')
return nX * nY + nZ;
if (chOperation == '*' && chOperation2 == '-')
return nX * nY - nZ;
if (chOperation == '*' && chOperation2 == '*')
return nX * nY * nZ;
if (chOperation == '*' && chOperation2 == '/')
return nX * nY / nZ;
if (chOperation == '/' && chOperation2 == '+')
return nX / nY + nZ;
if (chOperation == '/' && chOperation2 == '-')
return nX / nY - nZ;
if (chOperation == '/' && chOperation2 == '*')
return nX / nY * nZ;
if (chOperation == '/' && chOperation2 == '/')
return nX / nY / nZ;
return 0;
}

Cách ánh xạ các yêu cầu đến thư mục bên ngoài Tôi có một thư mục/ứng dụng nằm ngoài thư mục gốc web của trang web của tôi. Ví dụ, trang web ở đây:

/var/www/site/htdocs/

Và ứng dụng bên ngoài ở đây:

/var/www/apps/coolapp/

Câu hỏi của tôi là làm thế nào để tôi có thể cấu hình nginx để ánh xạ/đường dẫn tất cả các yêu cầu giống như "www.mysite.com/coolapp/*" (dấu sao là ký tự đại diện) đến vị trí bên ngoài "/var/www/apps/coolapp/"? Ví dụ, www.mysite.com/coolapp/test.php nên phục vụ "/var/www/apps/coolapp/test.php". Theo câu trả lời của @krokola, tôi đã thử thêm chỉ thị "alias" trong tệp "production.conf" mà tệp "nginx.conf" chính bao gồm. Đây là cách "production.conf" hiện tại trông như thế nào

server {
    listen 80;
    listen 443 ssl;
    ssl_certificate /blah/blah/blah;
    ssl_certificate_key /blah/blah/blah;
    ssl_protocols blah blah blah;
    ssl_ciphers blahblahblah;
    ssl_prefer_server_ciphers blahblah;
    access_log /var/log/nginx/www.mysite.com-access.log;
    error_log /var/log/nginx/www.mysite.com-error.log error;
    server_name mysite.com www.mysite.com;
    root /var/www/site/htdocs;
    include conf/magento_rewrites.conf;
    include conf/magento_security.conf;
    include /var/www/site/nginx/*.conf;
    #-------MÃ LỜI CÂU HỎI------
    location /coolapp/ {
        alias /var/www/apps/coolapp/;
        location ~ \.php {
            # Sao chép từ "# PHP Handler" bên dưới
            fastcgi_param MAGE_RUN_CODE default;
            fastcgi_param MAGE_RUN_TYPE store;
            fastcgi_param HTTPS $fastcgi_https;
            rewrite_log on;
            # Theo mặc định, chỉ xử lý fcgi mà không có bộ nhớ đệm
            include conf/magento_fcgi.conf;
        }
    }
    # Xử lý PHP
    location ~ \.php {
        ## Bắt các lỗi 404 mà try_files bỏ lỡ
        if (!-e $request_filename) { rewrite / /index.php last; }
        ## Mã cửa hàng được xác định trong quản trị > Cấu hình > Quản lý cửa hàng
        fastcgi_param MAGE_RUN_CODE default;
        fastcgi_param MAGE_RUN_TYPE store;
        fastcgi_param HTTPS $fastcgi_https;
        rewrite_log on;
        # Theo mặc định, chỉ xử lý fcgi mà không có bộ nhớ đệm
        include conf/magento_fcgi.conf;
    }
    # Các lỗi 404 được xử lý bởi bộ điều khiển phía trước
    location @magefc {
        rewrite ^(.*) /index.php?$query_string last;
    }
    # Đường dẫn cuối cùng giao cho magento hoặc đặt bộ nhớ đệm toàn cầu
    location / {
        ## Trang bảo trì ghi đè lên bộ điều khiển phía trước
        index index.html index.php;
        try_files $uri $uri/ @magefc;
        expires 24h;
    }
}
Tệp "conf/magento_fcgi.conf" trông như thế này:

fastcgi_pass phpfpm;
## Cho máy chủ phía sau biết ai đang thực hiện yêu cầu
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
