Liên kết trang lỗi/không hợp lệ được Googlebot phát hiện Yahoo gần đây đã mua Tumblr, nơi tôi viết những bài viết khoa học tương đối dài. Tôi nhận thấy gần đây một đoạn mã mới đã được thêm vào cuối trang và dường như nó đang tương tác xấu với các robot tìm kiếm của Google. Một lượt truy cập hôm nay đến “/post/:id/:summary” nơi rõ ràng chỉ là một số loại lược đồ trang web. Nó đến từ một trang trên _What is a gene, post-ENCODE?_ và khi tôi tìm kiếm tiêu đề này cụ thể cho trang web của tôi tôi cũng kéo lên một lượt truy cập thứ hai dường như giống hệt nhau tại /page/:page Tìm kiếm cho 'site:<siteURL>/:page' không có kết quả, giả sử do dấu chấm phẩy nhưng 'site:<siteURL>/post/:id/:summary' xác nhận rằng nó chỉ dành cho trang bài viết duy nhất này. Tôi đi đến trang 'xóa URL' trên Google Webmaster Tools nhưng nó nói trang vẫn đang hoạt động, nghĩa là nó hoặc đang xem bài viết của tôi hoặc toàn bộ trang chủ (khi bạn đi đến /post/:id/:summary bạn thực sự chỉ nhận được URL gốc, và tôi không muốn xóa nó khỏi Google!), khuyên tôi nên xóa nội dung trước khi yêu cầu xóa nó khỏi bộ nhớ cache của họ. Tôi không thể thấy cách lược đồ trang web này được tạo ra (ít nhất là /sitemap1.xml không cho nó như vậy), nhưng tìm kiếm cho “"/post/:id/:summary"“ đưa ra mã tương tự như những gì Yahoo đang thêm vào các trang web:

(function() { s = document.createElement('script'); el = document.getElementsByTagName('script')[0]; s.src = ('https:' == document.location.protocol ? 'https://s' : 'http://l') + '.yimg.com/ss/rapid-3.14.js'; s.onload = function(){ YAHOO = window.YAHOO; if (YAHOO) { YAHOO.i13n.beacon_server = 'nol.yahoo.com'; var keys = { pd:'/post/:id/:summary', _li:0, i_rad:0, i_strm:0, b_id:66209497 }; var conf = { spaceid:1197719230, client_only:1, yql_enabled:false, keys:keys } YAHOO.rapid = new YAHOO.i13n.Rapid(conf); } el.parentNode.insertBefore(s, el); })();

