PHP Caching Quá Lâu Tôi đã triển khai một hệ thống lưu trữ đơn giản trên trang web của tôi tuần trước sử dụng một lớp PHP được tham chiếu trong tập tin mẫu trên toàn bộ trang web. Hệ thống lưu trữ đã cải thiện đáng kể thời gian phản hồi máy chủ (mẫu lấy dữ liệu từ một vài máy chủ khác trong trung tâm dữ liệu của chúng tôi, vì vậy nó không được lưu trữ tất cả trong bộ nhớ bởi Apache). Vấn đề là nó đã lưu trữ quá nhiều tập tin. Tôi tin rằng tôi đã thiết lập nó để lưu trữ trong năm phút, hoặc cho đến khi HTML được sửa đổi, nhưng nó vẫn cung cấp các phiên bản được lưu trữ của các trang ngay cả sau khi các phiên bản được lưu trữ đã được tạo ra. Có ai phát hiện ra bất kỳ vấn đề nào với mã của tôi, hoặc bạn có biết bất kỳ phiên bản nào của PHP/Apache/Red Hat có thể, nói, báo cáo thông tin xấu về thời gian sửa đổi tập tin? (Chúng tôi đang sử dụng PHP 5.3.3, Apache 2.2.15 và RHEL 6. Tôi đã từng chạy mod_pagespeed, nhưng vấn đề vẫn tồn tại ngay cả sau khi tôi vô hiệu hóa nó.)

<?php
class IWU_Cache {
protected $cache_prefix = '/tmp/webcache_';
protected $remote_delay = 300; // trong giây; 300 là năm phút
protected $path;

public function __construct($path = '') {
$this->path = $path;
}

public function isRecentlyCached() {
$cache_location = $this->path2Cache($this->path);
nếu (is_file($cache_location)) {
nếu (is_file($_SERVER['DOCUMENT_ROOT'] . $this->path) && (filemtime($_SERVER['DOCUMENT_ROOT'] . $this->path) < filemtime($cache_location))) {
trả về TRUE;
}
ngược lại nếu (filemtime($cache_location) > time() - $this->remote_delay) {
trả về TRUE;
}
}

trả về FALSE;
}

public function getCachedVersion() {
trả về file_get_contents($this->path2Cache($this->path));
}

public function addToCache($html) {
trả về file_put_contents($this->path2Cache($this->path), $html);
}

bảo vệ chức năng path2Cache($path) {
trả về $this->cache_prefix . str_replace('/', '____', $path);
}
}
?>

