Theo dõi lần đăng nhập và lần truy cập cuối cùng Tôi đang sử dụng mã sau để theo dõi thời gian người dùng đăng nhập lần cuối. Tuy nhiên, tôi nhận ra rằng nếu họ chọn tùy chọn "Nhớ tôi", mã này sẽ không ghi lại thời gian **lần truy cập cuối cùng** của họ.

// Ghi lại thời gian người dùng đăng nhập và lưu lại

function set_last_login($login) {
  $user = get_userdatabylogin($login);
  update_usermeta( $user->ID, 'last_login', current_time('mysql') );
}

add_action('wp_login', 'set_last_login');

// Hàm hiển thị thời gian người dùng đăng nhập lần cuối

function get_last_login($user_id) {
  $last_login = get_user_meta($user_id, 'last_login', true);
  $date_format = get_option('date_format') . ' ' . get_option('time_format');
  $the_last_login = mysql2date($date_format, $last_login, false);
