function states_save_postdata( $post_id ) {
// Kiểm tra xem đây có phải là một quy trình tự động lưu không.
// Nếu đúng vậy, biểu mẫu của chúng tôi chưa được gửi, vì vậy chúng tôi không muốn làm gì cả
if ( ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) || wp_is_post_revision( $post_id ) )
return;
// Xác minh rằng nó đến từ màn hình của chúng tôi và với quyền xác thực phù hợp,
// vì save_post có thể được kích hoạt vào những thời điểm khác
if ( !wp_verify_nonce( $_POST['states_noncename'], plugin_basename( __FILE__ ) ) )
return;
// Kiểm tra quyền
if ( 'post' == $_POST['post_type'] ) {
if ( !current_user_can( 'edit_page', $post_id ) )
return;
} else {
if ( !current_user_can( 'edit_post', $post_id ) )
return;
}
// Được rồi, chúng tôi đã được xác thực: chúng tôi cần tìm và lưu dữ liệu
$states_ID = $_POST['states'];
$states = ( $states_ID > 0 ) ? get_term( $states_ID, 'states' )->slug : NULL;
wp_set_object_terms( $post_id , $states, 'states' );
}
