    }
}

add_action( 'edit_attachment', 'save_attachment_classes' );

Làm thế nào để ngăn chặn các trường tùy chỉnh bị xóa trong quá trình chỉnh sửa khối lượng lớn? Trong chức năng lưu giá trị trường tùy chỉnh của tôi, tôi đã thêm một vài kiểm tra để ngăn chặn các giá trị bị xóa trong quá trình tự động lưu hoặc chỉnh sửa nhanh.
add_action('save_post', 'save_my_post');
function save_my_post($post_id)
{
    // Ngăn WordPress xóa các trường tùy chỉnh trong quá trình tự động lưu,
    // và cũng trong các yêu cầu AJAX (ví dụ như chỉnh sửa nhanh).
    if ((defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) || (defined('DOING_AJAX') && DOING_AJAX))
        return;

    // Làm sạch, xác thực và lưu các trường tùy chỉnh
    $myfield = (!isset($_POST['myfield'])) ? '' : strval($_POST['myfield']);
    update_post_meta($post_id, 'myfield', $myfield);
}
Tuy nhiên, có vẻ như các trường tùy chỉnh vẫn bị xóa trong trường hợp chỉnh sửa hàng loạt. Các kiểm tra DOING_AUTOSAVE và DOING_AJAX không áp dụng cho việc chỉnh sửa hàng loạt. Tôi nhận ra rằng bạn có thể không gọi update_post_meta nếu các biến $_POST tương ứng không được thiết lập. Tuy nhiên, điều này sẽ không hoạt động trong trường hợp hộp kiểm. Lý tưởng nhất là có một kiểm tra đơn giản để xác định xem chúng ta có đang thực hiện chỉnh sửa hàng loạt hay không. Các ý tưởng nào?

