Đoạn mã cho hàm wpld_pagenavi() để tạo ra phần điều hướng trang:

function wpld_pagenavi() {
global $wp_query, $wp_rewrite;
$pages = '';
$max = $wp_query->max_num_pages;
if (!$current = get_query_var('paged'))
$current = 1;
$a['base'] = ($wp_rewrite->using_permalinks()) ? user_trailingslashit(trailingslashit(remove_query_arg('s', get_pagenum_link(1))) . 'page/%#%/', 'paged') : @add_query_arg('paged', '%#%');
if (!empty($wp_query->query_vars['s']))
$a['add_args'] = array('s' => get_query_var('s'));
$a['total'] = $max;
$a['current'] = $current;
$total = 1; //1 - hiển thị văn bản "Trang N của N", 0 - không hiển thị
$a['mid_size'] = 5; //hiển thị bao nhiêu liên kết ở hai bên trái và phải của trang hiện tại
$a['end_size'] = 1; //hiển thị bao nhiêu liên kết ở đầu và cuối
$a['prev_text'] = '&laquo; Previous'; //văn bản của liên kết "Trang trước"
$a['next_text'] = 'Next &raquo;'; //văn bản của liên kết "Trang tiếp theo"
if ($max > 1)
echo '<div class="navigation">';
if ($total == 1 && $max > 1)
$pages = '<span class="pages">Page ' . $current . ' of ' . $max . '</span>' . "\r\n";
echo $pages . paginate_links($a);
if ($max > 1)
echo '</div>';
}

