/**
* Khởi tạo một đối tượng WP_Query với các tham số tìm kiếm đã cho
*
* @since 1.0
*/
function query() {
$this->build_tax_query();
$this->build_meta_query();
$this->convert_orderby();
// Áp dụng phân trang
if ( get_query_var('paged') ) {
$paged = get_query_var('paged');
} else if ( get_query_var('page') ) {
$paged = get_query_var('page');
} else {
$paged = 1;
}
$this->wp_query_args['paged'] = $paged;
$this->wp_query = new WP_Query($this->wp_query_args);
$query = $this->wp_query;
$query->query_vars['post_type'] = $this->wp_query_args['post_type'];
if ($this->relevanssi) {
include_once( ABSPATH . 'wp-admin/includes/plugin.php' );
if (!empty($_REQUEST['search_query']) && is_plugin_active('relevanssi/relevanssi.php')) {
relevanssi_do_query($query);
}
}
if (defined('WPAS_DEBUG') && WPAS_DEBUG) {
echo '<pre>';
print_r($query);
echo '</pre>';
}
return $query;
}

/**
* Hiển thị các liên kết phân trang
*
* @since 1.0
*/
function pagination( $args = '' ) {
global $wp_query;
$current_page = max(1, get_query_var('paged'));
$total_pages = $wp_query->max_num_pages;
$big = '999999999';
$base = str_replace( $big, '%#%', esc_url( get_pagenum_link( $big ) ) );
$defaults = array(
'base' => $base,
'format' => 'page/%#%',
'current' => $current_page,
'total' => $total_pages
);
$args = wp_parse_args($args, $defaults);
if ($total_pages > 1){
echo '<div class="pagination">';
echo paginate_links($args);
echo '</div>';
}
}

/**
* Hiển thị phạm vi kết quả hiển thị trên trang hiện tại
*
* @since 1.0
*/
function results_range( $args = array() ) {
global $wp_query;
$defaults = array(
'pre' => '',
'marker' => '-',
'post' => ''
);
$args = wp_parse_args($args, $defaults);
extract($args);
$total = $wp_query->found_posts;
$count = $wp_query->post_count;
$query = $wp_query->query;
$ppp = (!empty($query['posts_per_page'])) ? $query['posts_per_page'] : get_option('posts_per_page');
$page =  get_query_var('paged');
$range = 1;
$range = $page;
if ($ppp > 1) {
$i = 1 + (($page - 1)*$ppp);
$j = $i + ($ppp - 1);
$range = sprintf('%d%s%d', $i, $marker, $j);
if ($j > $total) {
$range = $total;
}
}
if ($count < 1) {
$range = 0;
}
$output = sprintf('<span>%s</span> <span>%s</span> <span>%s</span>', $pre, $range, $post);
return $output;
}

