// Mã ngắn
hàm cptbc_shortcode($atts, $content = null) {
// Thiết lập các thuộc tính mã ngắn mặc định
$defaults = array(
'interval' => '5000',
'showcaption' => 'true',
'showcontrols' => 'true'
);
// Phân tích các thuộc tính $atts đến một mảng và kết hợp nó với $defaults
$atts = shortcode_atts($defaults, $atts);
// Trả về cptbc_frontend($atts);
}
thêm_mã ngắn('image-carousel', 'cptbc_shortcode');
// Hiển thị WftC mới nhất
hàm cptbc_frontend($atts){
$id = rand(0, 999); // sử dụng ID ngẫu nhiên để các ID CSS hoạt động với nhiều trên một trang
$args = array( 'post_type' => 'cptbc', 'orderby' => 'menu_order', 'order' => 'ASC');
$loop = new WP_Query( $args );
$images = array();
trong khi ( $loop->have_posts() ) {
$loop->the_post();
nếu ( '' != get_the_post_thumbnail() ) {
$title = get_the_title();
$content = get_the_excerpt();
$image = get_the_post_thumbnail( get_the_ID(), 'full' );
$link = get_post_custom_values('link');
$images[] = array('title' => $title, 'content' => $content, 'image' => $image, 'link' => $link);
}
}
nếu (count($images) > 0){
ob_start();
?>
<div id="cptbc_<?php echo $id; ?>" class="carousel slide">
<ol class="carousel-indicators">
<?php foreach ($images as $key => $image) { ?>
<li data-target="#cptbc_<?php echo $id; ?>" data-slide-to="<?php echo $key; ?>" data-interval="<?php echo $atts['interval']; ?>" <?php echo $key == 0 ? 'class="active"' : ''; ?>></li>
<?php } ?>
</ol>
<div class="carousel-inner">
<?php foreach ($images as $key => $image) { ?>
<div class="item <?php echo $key == 0 ? 'active' : ''; ?>">
<?php echo $image['image']; ?>
<?php if($atts['showcaption'] === 'true') { ?>
<div class="carousel-caption">
<h2><?php echo $image['title']; ?></h2>
<p class="lead"><?php echo $image['content']; ?></p>
<?php echo '<a class="btn btn-large btn-primary" href="' . $image['link'][0] . '">Läs mer</a>';?>
</div>
<?php } ?>
</div>
<?php } ?>
</div>
<?php nếu ($atts['showcontrols'] === 'true') { ?>
<a class="left carousel-control" href="#cptbc_<?php echo $id; ?>" data-slide="prev">‹</a>
<a class="right carousel-control" href="#cptbc_<?php echo $id; ?>" data-slide="next">›</a>
<?php } ?>
</div>
<?php
}
$output = ob_get_contents();
ob_end_clean();
// Khôi phục dữ liệu bài viết ban đầu
wp_reset_postdata();
trả về $output;
}
// Gọi carousel trong JavaScript, nếu không nó sẽ không tự động cuộn
hàm cptbc_footer_js() {
?>
<script type="text/javascript">
jQuery(function(){
jQuery('.carousel').carousel()
});
</script>
<?php
}
add_action('wp_footer', 'cptbc_footer_js');
?>
